    text = str(directory)
    if text in SHELL_SCOPE_BLOCK_DIRS or len(directory.parts) < SHELL_SCOPE_MIN_PARTS:
        return False
    try:
        anchors = (Path.home().resolve(), root.resolve())
    except OSError:
